#include <stdio.h>
#include <stdlib.h>

#define MAX_COEFF   13          /* maximum number of coefficients */
#define MAX_COEFF_ABS 1000      /* |coefficient| must be <= 1000 */
#define MAX_X_ABS   10          /* |x| must be <= 10 */

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr;
    long x = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (x > MAX_X_ABS || x < -MAX_X_ABS) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (argc == 2) {
        puts("EMPTY");
        return 0;
    }

    int ncoeff = argc - 2;
    if (ncoeff > MAX_COEFF) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long coeff[MAX_COEFF];
    for (int i = 0; i < ncoeff; ++i) {
        char *c_end;
        long c = strtol(argv[2 + i], &c_end, 10);
        if (*c_end != '\0') {
            puts("BAD_INPUT");
            return 0;
        }
        if (c > MAX_COEFF_ABS || c < -MAX_COEFF_ABS) {
            puts("OUT_OF_RANGE");
            return 0;
        }
        coeff[i] = c;
    }

    long result = 0;
    for (int i = 0; i < ncoeff; ++i) {
        result = result * x + coeff[i];
    }

    printf("%lld\n", result);
    return 0;
}
